import base64
from lxml import etree
from .validator import SignatureValidator


class SAMLResponseParser:

    NAMESPACES = {
        'samlp': 'urn:oasis:names:tc:SAML:2.0:protocol',
        'saml': 'urn:oasis:names:tc:SAML:2.0:assertion',
        'ds': 'http://www.w3.org/2000/09/xmldsig#'
    }

    def __init__(self, saml_response_b64, cert_text, 
                 validate_time=True,
                 validate_audience=False,
                 expected_audience=None,
                 validate_destination=False,
                 expected_destination=None,
                 time_tolerance=300):
        self.saml_response_b64 = saml_response_b64
        self.cert_text = cert_text
        self.document = None
        self.assertions = []
        self.validate_time = validate_time
        self.validate_audience = validate_audience
        self.expected_audience = expected_audience
        self.validate_destination = validate_destination
        self.expected_destination = expected_destination
        self.time_tolerance = time_tolerance
        self._processed_assertion_ids = set()

    def parse(self):
        try:
            decoded = base64.b64decode(self.saml_response_b64)
            parser = etree.XMLParser(resolve_entities=False, no_network=True)
            self.document = etree.fromstring(decoded, parser)
            return True
        except Exception as e:
            return False

    def validate_signature(self):
        if self.document is None:
            return False

        validator = SignatureValidator(
            self.document, 
            self.cert_text,
            validate_time=self.validate_time,
            validate_audience=self.validate_audience,
            expected_audience=self.expected_audience,
            validate_destination=self.validate_destination,
            expected_destination=self.expected_destination,
            time_tolerance=self.time_tolerance
        )
        return validator.validate()

    def get_nameid(self):
        if self.document is None:
            return None

        assertions = self.document.xpath(
            '//saml:Assertion',
            namespaces=self.NAMESPACES
        )

        if not assertions:
            return None

        assertion = assertions[0]
        nameid_nodes = assertion.xpath(
            './/saml:NameID',
            namespaces=self.NAMESPACES
        )

        if nameid_nodes:
            return nameid_nodes[0].text

        return None

    def get_attributes(self):
        if self.document is None:
            return {}

        attributes = {}

        assertions = self.document.xpath(
            '//saml:Assertion',
            namespaces=self.NAMESPACES
        )

        if not assertions:
            return attributes

        assertion = assertions[0]
        attr_nodes = assertion.xpath(
            './/saml:Attribute',
            namespaces=self.NAMESPACES
        )

        for attr in attr_nodes:
            name = attr.get('Name')
            values = attr.xpath(
                './/saml:AttributeValue',
                namespaces=self.NAMESPACES
            )
            if values:
                attributes[name] = values[0].text

        return attributes

    def is_valid(self):
        if not self.parse():
            return False

        if not self.validate_signature():
            return False

        if not self._check_assertion_uniqueness():
            return False

        return True

    def _check_assertion_uniqueness(self):
        try:
            assertion_nodes = self.document.xpath(
                '//saml:Assertion',
                namespaces=self.NAMESPACES
            )

            for assertion in assertion_nodes:
                assertion_id = assertion.get('ID')
                if assertion_id:
                    if assertion_id in self._processed_assertion_ids:
                        return False
                    self._processed_assertion_ids.add(assertion_id)

            return True
        except Exception:
            return False

    def get_assertion_ids(self):
        try:
            assertion_nodes = self.document.xpath(
                '//saml:Assertion',
                namespaces=self.NAMESPACES
            )

            ids = []
            for assertion in assertion_nodes:
                assertion_id = assertion.get('ID')
                if assertion_id:
                    ids.append(assertion_id)

            return ids
        except Exception:
            return []


def _apply_transforms(self, element, transforms_nodes):
    try:
        element_copy = copy.deepcopy(element)

        for transform in transforms_nodes:
            algorithm = transform.get('Algorithm', '')

            if 'enveloped-signature' in algorithm:
                sig_nodes = element_copy.xpath(
                    './/*[local-name()="Signature" and namespace-uri()="http://www.w3.org/2000/09/xmldsig#"]'
                )
                for sig in sig_nodes:
                    parent = sig.getparent()
                    if parent is not None:
                        parent.remove(sig)

        return element_copy
    except Exception as e:
        return element

def _calculate_digest(self, element, hash_algorithm):
    try:
        from cryptography.hazmat.primitives.hashes import Hash

        c14n_bytes = self._canonicalize(element)
        if c14n_bytes is None:
            return None

        digest = Hash(hash_algorithm, backend=default_backend())
        digest.update(c14n_bytes)
        digest_value = digest.finalize()

        return digest_value
    except Exception as e:
        return None

def _verify_reference(self, reference_node, signature_node):
    try:
        uri = reference_node.get('URI')
        if not uri:
            return False

        ref_id = uri[1:] if uri.startswith('#') else uri

        signed_elements = self.document.xpath(
            f'//*[@ID="{ref_id}"]'
        )

        if not signed_elements:
            return False

        signed_element = signed_elements[0]

        transforms_nodes = reference_node.xpath(
            './ds:Transforms/ds:Transform',
            namespaces=self.NAMESPACES
        )

        transformed_element = self._apply_transforms(signed_element, transforms_nodes)

        digest_hash = self._get_digest_method(reference_node)

        calculated_digest = self._calculate_digest(transformed_element, digest_hash)
        if calculated_digest is None:
            return False

        digest_value_nodes = reference_node.xpath(
            './ds:DigestValue',
            namespaces=self.NAMESPACES
        )

        if not digest_value_nodes:
            return False

        expected_digest = base64.b64decode(digest_value_nodes[0].text.strip())

        return calculated_digest == expected_digest

    except Exception as e:
        return False

def _verify_signature(self, signature_node):
    try:
        signed_info_nodes = signature_node.xpath(
            './ds:SignedInfo',
            namespaces=self.NAMESPACES
        )

        if not signed_info_nodes:
            return False

        signed_info = signed_info_nodes[0]

        reference_nodes = signed_info.xpath(
            './ds:Reference',
            namespaces=self.NAMESPACES
        )

        if not reference_nodes:
            return False

        for reference_node in reference_nodes:
            if not self._verify_reference(reference_node, signature_node):
                return False

        signed_info_c14n = self._canonicalize(signed_info)
        if signed_info_c14n is None:
            return False

        hash_algorithm = self._get_signature_method(signed_info)

        sig_value_nodes = signature_node.xpath(
            './ds:SignatureValue',
            namespaces=self.NAMESPACES
        )

        if not sig_value_nodes:
            return False

        signature_value_text = sig_value_nodes[0].text
        if not signature_value_text:
            return False

        signature_value = base64.b64decode(signature_value_text.strip())

        try:
            self.public_key.verify(
                signature_value,
                signed_info_c14n,
                padding.PKCS1v15(),
                hash_algorithm
            )
            return True
        except Exception as e:
            return False

    except Exception as e:
        return False

def _validate_time_conditions(self):
    try:
        conditions_nodes = self.document.xpath(
            '//saml:Conditions',
            namespaces=self.NAMESPACES
        )

        if not conditions_nodes:
            return True

        now = datetime.utcnow()
        tolerance = timedelta(seconds=self.time_tolerance)

        for conditions in conditions_nodes:
            not_before = conditions.get('NotBefore')
            if not_before:
                not_before_time = self._parse_time(not_before)
                if not_before_time and now < (not_before_time - tolerance):
                    return False

            not_on_or_after = conditions.get('NotOnOrAfter')
            if not_on_or_after:
                not_on_or_after_time = self._parse_time(not_on_or_after)
                if not_on_or_after_time and now > (not_on_or_after_time + tolerance):
                    return False

        confirmation_data_nodes = self.document.xpath(
            '//saml:SubjectConfirmationData',
            namespaces=self.NAMESPACES
        )

        for confirmation_data in confirmation_data_nodes:
            not_on_or_after = confirmation_data.get('NotOnOrAfter')
            if not_on_or_after:
                not_on_or_after_time = self._parse_time(not_on_or_after)
                if not_on_or_after_time and now > (not_on_or_after_time + tolerance):
                    return False

        return True
    except Exception:
        return False

def _validate_audience_restriction(self):
    """
    """
    try:
        if not self.expected_audience:
            return True

        audience_nodes = self.document.xpath(
            '//saml:Audience',
            namespaces=self.NAMESPACES
        )

        if not audience_nodes:
            return False

        for audience in audience_nodes:
            if audience.text and audience.text.strip() == self.expected_audience:
                return True

        return False
    except Exception:
        return False

def _validate_destination(self):
    """
    """
    try:
        if not self.expected_destination:
            return True

        response_nodes = self.document.xpath(
            '//samlp:Response',
            namespaces=self.NAMESPACES
        )

        for response in response_nodes:
            destination = response.get('Destination')
            if destination and destination != self.expected_destination:
                return False

const config = require('../config/config');

const User = require('../models/User');
const { validationResult } = require('express-validator');


class AuthController {
    static showRegister(req, res) {
        res.render('register', {
            title: 'User Registration',
            errors: [],
            formData: {}
        });
    }

    static async register(req, res) {
        const errors = validationResult(req);

        if (!errors.isEmpty()) {
            return res.render('register', {
                title: 'User Registration',
                errors: errors.array(),
                formData: req.body
            });
        }

        const { username, email, password, type, invitationCode, displayName, department } = req.body;

        try {
            const existingUser = await User.findByUsername(username);
            if (existingUser) {
                return res.render('register', {
                    title: 'User Registration',
                    errors: [{ msg: 'Username already exists' }],
                    formData: req.body
                });
            }

            const existingEmail = await User.findByEmail(email);
            if (existingEmail) {
                return res.render('register', {
                    title: 'User Registration',
                    errors: [{ msg: 'Email already registered' }],
                    formData: req.body
                });
            }


            if (parseInt(type) === 0) {
                if (!invitationCode || invitationCode !== config.getInviteCode()) {
                    return res.render('register', {
                        title: 'User Registration',
                        errors: [{ msg: 'Invalid invitation code' }],
                        formData: req.body
                    });
                }

            }

            req.session.userId = await User.create({
                username,
                email,
                password,
                type,
                displayName: displayName || username,
                department,
                role: 'user'
            });
            req.session.username = username;
            req.session.userType = type;
            req.session.userRole = 'user';

            res.redirect('/portal');
        } catch (error) {
            console.error('[Auth] User registration failed:', error.message);
            console.error(error);
            res.render('register', {
                title: 'User Registration',
                errors: [{ msg: 'Registration failed, please try again later' }],
                formData: req.body
            });
        }
    }

    static showLogin(req, res) {
        const samlRequest = req.query.SAMLRequest || '';
        const relayState = req.query.RelayState || '';
        const oauth2Params = {
            clientId: req.query.client_id || '',
            redirectUri: req.query.redirect_uri || '',
            responseType: req.query.response_type || '',
            state: req.query.state || '',
            scope: req.query.scope || ''
        };

        res.render('login', {
            title: 'User Login',
            errors: [],
            formData: {},
            samlRequest,
            relayState,
            oauth2Params
        });
    }

    static async login(req, res) {
        const { username, password } = req.body;
        const samlRequest = req.body.samlRequest || '';
        const relayState = req.body.relayState || '';

        try {
            const user = await User.findByUsername(username);

            if (!user) {
                return res.render('login', {
                    title: 'User Login',
                    errors: [{ msg: 'Invalid username or password' }],
                    formData: { username },
                    samlRequest,
                    relayState,
                    oauth2Params: {}
                });
            }

            const isValidPassword = await User.verifyPassword(password, user.password);

            if (!isValidPassword) {
                return res.render('login', {
                    title: 'User Login',
                    errors: [{ msg: 'Invalid username or password' }],
                    formData: { username },
                    samlRequest,
                    relayState,
                    oauth2Params: {}
                });
            }

            await User.updateLastLogin(user.id);

            req.session.userId = user.id;
            req.session.username = user.username;
            req.session.userType = user.type;
            req.session.userRole = user.role;
            req.session.userEmail = user.email;
            req.session.displayName = user.display_name || user.username;

            if (samlRequest) {
                return res.redirect(`/saml/sso?SAMLRequest=${encodeURIComponent(samlRequest)}&RelayState=${encodeURIComponent(relayState)}`);
            }

            const oauth2ClientId = req.body.oauth2ClientId || req.query.client_id;
            if (oauth2ClientId) {
                const params = new URLSearchParams({
                    client_id: oauth2ClientId,
                    redirect_uri: req.body.oauth2RedirectUri || req.query.redirect_uri,
                    response_type: req.body.oauth2ResponseType || req.query.response_type || 'code',
                    state: req.body.oauth2State || req.query.state || '',
                    scope: req.body.oauth2Scope || req.query.scope || 'profile'
                });
                return res.redirect(`/oauth/authorize?${params.toString()}`);
            }

            res.redirect('/portal');
        } catch (error) {
            console.error('[Auth] User login failed:', error.message);
            console.error(error);
            res.render('login', {
                title: 'User Login',
                errors: [{ msg: 'Login failed, please try again later' }],
                formData: { username },
                samlRequest,
                relayState,
                oauth2Params: {}
            });
        }
    }

    static async logout(req, res) {
        req.session.destroy((err) => {
            if (err) {
                console.error('[Auth] Session destroy failed:', err.message);
            }
            res.redirect('/');
        });
    }

    static async getCurrentUser(req, res) {
        try {
            const user = await User.findById(req.session.userId);

            if (!user) {
                return res.status(404).json({ error: 'User does not exist' });
            }

            res.json({
                success: true,
                data: User.sanitizeUser(user)
            });
